USE sakila;

## Challenge - Joining on multiple tables

#1 the number of films per category
SELECT c.name AS category_name, COUNT(f.film_id) AS number_of_films
FROM category c
JOIN film_category fc ON c.category_id = fc.category_id
JOIN film f ON fc.film_id = f.film_id
GROUP BY c.name
ORDER BY number_of_films DESC;

#2 the store ID, city, and country for each store.
SELECT s.store_id, ci.city, co.country
FROM store s
JOIN address a ON s.address_id = a.address_id
JOIN city ci ON a.city_id = ci.city_id
JOIN country co ON ci.country_id = co.country_id;

#3 the total revenue generated by each store in dollars.
SELECT s.store_id, SUM(p.amount) AS total_revenue
FROM payment p
JOIN rental r ON p.rental_id = r.rental_id
JOIN inventory i ON r.inventory_id = i.inventory_id
JOIN store s ON i.store_id = s.store_id
GROUP BY s.store_id
ORDER BY total_revenue DESC;

#4 the average running time of films for each category.

SELECT c.name AS category_name, AVG(f.length) AS average_runtime
FROM category c
JOIN film_category fc ON c.category_id = fc.category_id
JOIN film f ON fc.film_id = f.film_id
GROUP BY c.name
ORDER BY average_runtime DESC;

#5 to identify the film categories with the longest average running time.
SELECT c.name AS category_name, AVG(f.length) AS average_runtime
FROM category c
JOIN film_category fc ON c.category_id = fc.category_id
JOIN film f ON fc.film_id = f.film_id
GROUP BY c.name
ORDER BY average_runtime DESC;

#6 to display the top 10 most frequently rented movies in descending order.
SELECT f.title, COUNT(r.rental_id) AS rental_count
FROM rental r
JOIN inventory i ON r.inventory_id = i.inventory_id
JOIN film f ON i.film_id = f.film_id
GROUP BY f.title
ORDER BY rental_count DESC
LIMIT 10;

#7 we determine if "Academy Dinosaur" can be rented from Store 1
SELECT f.title, i.inventory_id, i.store_id
FROM film f
JOIN inventory i ON f.film_id = i.film_id
WHERE f.title = 'Academy Dinosaur' AND i.store_id = 1;

#8 a list of all distinct film titles, along with their availability status in the inventory
SELECT f.title, i.inventory_id,
       CASE WHEN IFNULL(i.inventory_id, 0) = 0 THEN 'NOT available' ELSE 'Available' END AS availability_status
FROM film f
LEFT JOIN inventory i ON f.film_id = i.film_id
GROUP BY f.title, i.inventory_id
ORDER BY availability_status DESC;


SELECT f.title AS 'NOT available'
FROM film f
LEFT JOIN inventory i ON f.film_id = i.film_id
WHERE IFNULL(i.inventory_id, 0) = 0
GROUP BY f.title
ORDER BY f.title  ;


